var t=`0740-kitfo`;var n=`world-0740`;var a=`ET`;var s=`eastern-africa`;var o=4;var r=22;var d={en:`Kitfo`,ua:`Кітфо`};var l={en:`Kitfo is a Ethiopia classic prepared with yellow onion, niter kibbeh, mitmita, ground beef. A measured home-style version, with ingredients assigned to the cooking steps where they are used. This is a fully cooked kitfo-style adaptation. Traditional kitfo is often raw or lightly cooked and requires specialist raw-meat handling.`,ua:`Кітфо, страва кухні країни Ефіопія зі складниками: жовта цибуля, пряне масло нітер кіббе, мітміта, яловичий фарш. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Це повністю термічно оброблена адаптація кітфо. Традиційно м’ясо часто сире або ледь прогріте й потребує спеціального контролю безпеки.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,90,`g`],[`niter-kibbeh`,65,`g`],[`mitmita`,12,`g`]]},{en:`Cook minced beef in the spiced butter over medium heat until fully browned with no raw center; this is a cooked kitfo-style serving.`,ua:`Готуйте яловичий фарш у пряному маслі на середньому вогні до повного прожарювання без сирої середини; це термічно оброблений кітфо.`,t:[`pan-frying`],m:10,i:[[`ground-beef`,650,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`injera`,4,`pcs`],[`farmer-cheese`,160,`g`]]}];var h={slug:t,id:n,country:`ET`,region:s,servings:4,minutes:22,title:d,text:l,steps:g};export{a as country,h as default,n as id,r as minutes,s as region,o as servings,t as slug,g as steps,l as text,d as title};